function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#87CEEB");
  brush.beginShape(0.5);
  brush.vertex(0, 100);
  brush.vertex(200, 100);
  brush.vertex(200, 0);
  brush.endShape(true);

  // Hills
  brush.fill("#228B22");
  brush.beginShape(0.5);
  brush.vertex(0, 150);
  brush.vertex(200, 150);
  brush.vertex(200, 100);
  brush.endShape(true);

  // Sun
  brush.fill("#FFD700");
  brush.beginShape(0.5);
  brush.vertex(200, 50);
  brush.vertex(190, 60);
  brush.vertex(210, 60);
  brush.endShape(true);
}
```

